                    ps.setLong(2, chainId);
                    ps.setLong(3, zoneId);
                    ps.setTimestamp(4, Timestamp.valueOf(frozenAt));
                    ps.setTimestamp(5, Timestamp.valueOf(windowStart));
                    ps.setTimestamp(6, Timestamp.valueOf(windowEnd));
                    if (lastTightenedAt == null) {
