194	    private IdempotencyService.Stored doIngestReading(long zoneId, IngestReadingRequest request) {
195	        ZoneRow zone = repository.findZoneByIdForUpdate(zoneId).orElseThrow(
196	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
197	
198	        // 归档为终态：归档时刻之前（含）的迟到位移只记迟到事件，不进入速率曲线。
199	        var archived = repository.findLatestArchivedChainByZone(zoneId);
200	        if (archived.isPresent() && !request.measuredAt().isAfter(archived.get().archivedAt())) {
201	            repository.insertLateEvent(zoneId, archived.get().id(), request.measuredAt(),
202	                    request.displacementMm(), "ARCHIVED_LATE_DATA");
203	            return json(201, new ReadingResponse(null, false, true, null, null,
204	                    "NONE", null, zone.status()));
205	        }
206	
207	        // 监测数据按“测区＋时刻”去重。
208	        var duplicated = repository.findReading(zoneId, request.measuredAt());
209	        if (duplicated.isPresent()) {
210	            ReadingRow existing = duplicated.get();
211	            return json(200, new ReadingResponse(existing.id(), true, false,
212	                    existing.hourlyRate(), existing.dailyRate(), "NONE", null, zone.status()));
213	        }
214	
215	        repository.insertReading(zoneId, request.measuredAt(), request.displacementMm());
216	        recomputeZoneRates(zoneId);
217	        ReadingRow reading = repository.findReading(zoneId, request.measuredAt()).orElseThrow();
218	
219	        String evaluation = evaluateAlarm(zone, reading);
220	        Long chainId = repository.findExecutingChainByZone(zoneId).map(ChainRow::id).orElse(null);
221	        ZoneRow current = repository.findZoneById(zoneId).orElseThrow();
222	        return json(201, new ReadingResponse(reading.id(), false, false,
223	                reading.hourlyRate(), reading.dailyRate(), evaluation, chainId, current.status()));
224	    }
