                threshold.reductionApplied(),
                threshold.dataSufficient() ? threshold.rainSum24h() : null,
                safetyLine, true));
    }
    return new SafetyGate(windowStart, lastTightenedAt, List.copyOf(moments),
            repository.findPolicyVersionsByZone(zone.id()));
}

